# Generated by test-lab — blind adversarial evaluation
"""
Blind evaluation checks for Express.js / TypeScript API servers.

Verifies Express server files (*.ts in server/) against conventions:
1. TypeScript server files exist
2. Express app initialisation
3. CORS middleware
4. JSON body parser
5. WebSocket (ws) support
6. Architecture plan endpoint (/plan) — POST /api/architecture/:id/plan
7. Memory daemon proxy
8. Health endpoint
9. Error handling (try/catch)
10. Static file serving

Inputs: target directory path (e.g. packages/ux-lab/server/)
Outputs: list[TestCheck] results
Failure modes: unreadable files (skipped)
"""

from __future__ import annotations

import sys
from pathlib import Path

from loguru import logger

_parent = str(Path(__file__).parent.parent)
if _parent not in sys.path:
    sys.path.insert(0, _parent)

from test_lab import TestCheck


# ---------------------------------------------------------------------------
# Checks
# ---------------------------------------------------------------------------

def run_checks(target_dir: Path) -> list[TestCheck]:
    """Run all Express/TypeScript best-practices checks against target directory."""
    checks: list[TestCheck] = []

    ts_files = list(target_dir.rglob("*.ts"))
    # Exclude node_modules, dist, .git
    ts_files = [
        f for f in ts_files
        if not any(part in f.parts for part in ("node_modules", "dist", ".git", ".venv"))
    ]

    # ── 1. TypeScript server files exist ─────────────────────────────────
    if not ts_files:
        checks.append(TestCheck(
            name="ts_files_exist",
            category="structure",
            passed=False,
            description="No .ts files found in target directory",
        ))
        return checks

    checks.append(TestCheck(
        name="ts_files_exist",
        category="structure",
        passed=True,
        description=f"Found {len(ts_files)} TypeScript file(s)",
    ))

    # Aggregate all content for cross-file checks
    combined = ""
    for f in ts_files:
        try:
            combined += f.read_text(encoding="utf-8") + "\n"
        except Exception as e:
            logger.warning("Could not read {}: {}", f, e)

    # ── 2. Express app initialisation ────────────────────────────────────
    has_express = "express()" in combined or "from 'express'" in combined or 'require("express")' in combined
    checks.append(TestCheck(
        name="express_init",
        category="conventions",
        passed=has_express,
        description=(
            "Express app initialised" if has_express
            else "Missing Express app initialisation (express())"
        ),
    ))

    # ── 3. CORS middleware ────────────────────────────────────────────────
    has_cors = "cors()" in combined or "app.use(cors" in combined
    checks.append(TestCheck(
        name="cors_middleware",
        category="conventions",
        passed=has_cors,
        description=(
            "CORS middleware configured" if has_cors
            else "Missing CORS middleware (app.use(cors()))"
        ),
    ))

    # ── 4. JSON body parser ───────────────────────────────────────────────
    has_json = "express.json()" in combined or "bodyParser.json" in combined
    checks.append(TestCheck(
        name="json_body_parser",
        category="conventions",
        passed=has_json,
        description=(
            "JSON body parser configured" if has_json
            else "Missing JSON body parser (express.json())"
        ),
    ))

    # ── 5. WebSocket support ──────────────────────────────────────────────
    has_ws = (
        "WebSocketServer" in combined
        or "new WebSocket" in combined
        or "ws.createServer" in combined
        or "wss" in combined
    )
    checks.append(TestCheck(
        name="websocket_support",
        category="correctness",
        passed=has_ws,
        description=(
            "WebSocket (ws) support present" if has_ws
            else "Missing WebSocket support — real-time agent canvas updates require ws"
        ),
    ))

    # ── 6. Architecture plan endpoint — POST /api/architecture/:id/plan ──
    has_plan_endpoint = (
        "/plan'" in combined
        or '/plan"' in combined
        or "'/plan'" in combined
        or '"/plan"' in combined
        or "/architecture/:id/plan" in combined
        or "architecture_plan" in combined
    )
    checks.append(TestCheck(
        name="architecture_plan_endpoint",
        category="correctness",
        passed=has_plan_endpoint,
        description=(
            "Architecture plan endpoint (POST /api/architecture/:id/plan) present" if has_plan_endpoint
            else "Missing plan endpoint — POST /api/architecture/:id/plan required for Create Plan button"
        ),
    ))

    # ── 7. Memory daemon proxy ────────────────────────────────────────────
    has_memory_proxy = (
        "memory.sock" in combined
        or "memoryRequest" in combined
        or "/api/memory" in combined
    )
    checks.append(TestCheck(
        name="memory_daemon_proxy",
        category="correctness",
        passed=has_memory_proxy,
        description=(
            "Memory daemon proxy present" if has_memory_proxy
            else "Missing memory daemon proxy — architecture persistence requires memory.sock"
        ),
    ))

    # ── 8. Health endpoint ────────────────────────────────────────────────
    has_health = "/api/health" in combined or "'/health'" in combined or '"/health"' in combined
    checks.append(TestCheck(
        name="health_endpoint",
        category="conventions",
        passed=has_health,
        description=(
            "Health endpoint present" if has_health
            else "Missing /api/health endpoint"
        ),
    ))

    # ── 9. Error handling ─────────────────────────────────────────────────
    has_try_catch = "try {" in combined or "try{" in combined or ".catch(" in combined
    checks.append(TestCheck(
        name="error_handling",
        category="correctness",
        passed=has_try_catch,
        description=(
            "Error handling (try/catch) present" if has_try_catch
            else "Missing error handling — wrap async handlers in try/catch"
        ),
    ))

    # ── 10. Static file serving ───────────────────────────────────────────
    has_static = "express.static" in combined or "sendFile" in combined
    checks.append(TestCheck(
        name="static_file_serving",
        category="conventions",
        passed=has_static,
        description=(
            "Static file serving configured" if has_static
            else "Missing static file serving (express.static)"
        ),
    ))

    return checks
